static void* work(void*arg){
  shared_t*S=(shared_t*)arg;
  EVP_CIPHER_CTX*ctx=EVP_CIPHER_CTX_new();
  if(!ctx){S->err=1;return NULL;}
  uint8_t iv[16]; memcpy(iv+4,S->nonce,12);
  int inited=0;
  for(;;){
    long ci=__sync_fetch_and_add(&S->next,1);
